char* alphabetBoardPath(char* target) {
    size_t n = strlen(target);
    char* res = (char*)malloc(n * 10 + 1);
    size_t p = 0;
    int r = 0, c = 0;
    for (size_t i = 0; i < n; i++) {
        int k = target[i] - 'a';
        int nr = k / 5, nc = k % 5;
        while (nr < r) { res[p++] = 'U'; r--; }
        while (nc < c) { res[p++] = 'L'; c--; }
        while (nc > c) { res[p++] = 'R'; c++; }
        while (nr > r) { res[p++] = 'D'; r++; }
        res[p++] = '!';
    }
    res[p] = '\0';
    return res;
}

