class Solution {
public:
    string alphabetBoardPath(string target) {
        string res = "";
        int r = 0, c = 0;
        for (char ch : target) {
            int k = ch - 'a';
            int nr = k / 5, nc = k % 5;
            if (nr < r) res.append(r - nr, 'U');
            if (nc < c) res.append(c - nc, 'L');
            if (nc > c) res.append(nc - c, 'R');
            if (nr > r) res.append(nr - r, 'D');
            res += '!';
            r = nr;
            c = nc;
        }
        return res;
    }
};

