class Solution {
    public String alphabetBoardPath(String target) {
        StringBuilder sb = new StringBuilder();
        int r = 0, c = 0;
        for (char ch : target.toCharArray()) {
            int idx = ch - 'a';
            int nr = idx / 5;
            int nc = idx % 5;
            for (int k = 0; k < r - nr; k++) sb.append('U');
            for (int k = 0; k < c - nc; k++) sb.append('L');
            for (int k = 0; k < nc - c; k++) sb.append('R');
            for (int k = 0; k < nr - r; k++) sb.append('D');
            sb.append('!');
            r = nr;
            c = nc;
        }
        return sb.toString();
    }
}

