class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        r, c = 0, 0
        res = []
        for ch in target:
            nr, nc = divmod(ord(ch) - 97, 5)
            if nr < r: res.append('U' * (r - nr))
            if nc < c: res.append('L' * (c - nc))
            if nc > c: res.append('R' * (nc - c))
            if nr > r: res.append('D' * (nr - r))
            res.append('!')
            r, c = nr, nc
        return "".join(res)

